deepml vfx 0.3
module corpus.deepml_vfx.example_04251
policy deterministic
policy no_network
effect Effect04251 {
  coupled simulation PortalSim seed 4251 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache5 interval 0s..10s step 1/60s hash sha256("cache:04251")
  bind scene PortalScene1
  bind timeline PortalSequence0
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

